// Pilot routes' types from the backend's OpenAPI schema (see scripts/api_contract.py).
// `npm run gen:api` writes the file; src/__tests__/api-contract.test.ts checks it is current.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";

const DIR = new URL("../src/lib/api/generated/", import.meta.url);
const HEADER =
  "// Generated by `npm run gen:api` from pilot-openapi.json. Do not edit; change the backend route instead.\n\n";

export async function render() {
  const schema = JSON.parse(readFileSync(new URL("pilot-openapi.json", DIR), "utf-8"));
  const ast = await openapiTS(schema);
  return HEADER + astToString(ast);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(new URL("pilot-schema.ts", DIR), await render());
  console.log("wrote src/lib/api/generated/pilot-schema.ts");
}
